import React, { useState, useRef, useEffect, KeyboardEvent, ChangeEvent } from "react";
// import styles from "./LoginPage.module.css";

type Step = "phone" | "otp" | "success";

const MOCK_OTP = "1234";

export default function LoginPage() {
  const [step, setStep] = useState<Step>("phone");
  const [phone, setPhone] = useState<string>("");
  const [otp, setOtp] = useState<string[]>(["", "", "", ""]);
  const [error, setError] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [resendTimer, setResendTimer] = useState<number>(0);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (resendTimer > 0) {
      timerRef.current = setInterval(() => {
        setResendTimer((t) => {
          if (t <= 1) {
            clearInterval(timerRef.current!);
            return 0;
          }
          return t - 1;
        });
      }, 1000);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [resendTimer]);

  const isValidPhone = (p: string): boolean => /^[6-9]\d{9}$/.test(p);

  const handleSendOTP = async (): Promise<void> => {
    if (!isValidPhone(phone)) {
      setError("Enter a valid 10-digit Indian mobile number.");
      return;
    }
    setError("");
    setLoading(true);
    await new Promise((r) => setTimeout(r, 1200));
    setLoading(false);
    setStep("otp");
    setResendTimer(30);
    setTimeout(() => otpRefs.current[0]?.focus(), 100);
  };

  const handleOtpChange = (i: number, val: string): void => {
    if (!/^\d?$/.test(val)) return;
    const next = [...otp];
    next[i] = val;
    setOtp(next);
    setError("");
    if (val && i < 3) otpRefs.current[i + 1]?.focus();
  };

  const handleOtpKeyDown = (i: number, e: KeyboardEvent<HTMLInputElement>): void => {
    if (e.key === "Backspace" && !otp[i] && i > 0) {
      otpRefs.current[i - 1]?.focus();
    }
  };

  const handleVerifyOTP = async (): Promise<void> => {
    const entered = otp.join("");
    if (entered.length < 4) {
      setError("Please enter the 4-digit OTP.");
      return;
    }
    if (entered !== MOCK_OTP) {
      setError("Incorrect OTP. Hint: try 1234 😉");
      return;
    }
    setError("");
    setLoading(true);
    await new Promise((r) => setTimeout(r, 1000));
    setLoading(false);
    setStep("success");
  };

  const handleResend = (): void => {
    if (resendTimer > 0) return;
    setOtp(["", "", "", ""]);
    setError("");
    setResendTimer(30);
    setTimeout(() => otpRefs.current[0]?.focus(), 100);
  };

  const handleReset = (): void => {
    setStep("phone");
    setPhone("");
    setOtp(["", "", "", ""]);
    setError("");
    setResendTimer(0);
  };

  return (
    <div className={styles.wrapper}>
      <div className={styles.blob} />
      <div className={styles.container}>
        <div className={styles.card}>
          <div className={styles.accentLine} />

          {/* ── PHONE STEP ── */}
          {step === "phone" && (
            <>
              <Logo />
              <h1 className={styles.title}>Welcome back</h1>
              <p className={styles.subtitle}>Sign in with your mobile number</p>

              <label className={styles.label}>Mobile Number</label>
              <div className={styles.phoneRow}>
                <div className={styles.flagBox}>🇮🇳 +91</div>
                <input
                  type="tel"
                  className={styles.phoneInput}
                  maxLength={10}
                  value={phone}
                  placeholder="98765 43210"
                  onChange={(e: ChangeEvent<HTMLInputElement>) => {
                    setPhone(e.target.value.replace(/\D/g, ""));
                    setError("");
                  }}
                  onKeyDown={(e) => e.key === "Enter" && handleSendOTP()}
                />
              </div>

              {error && <p className={styles.error}>{error}</p>}

              <button
                className={styles.btn}
                onClick={handleSendOTP}
                disabled={loading}
              >
                {loading ? <Spinner /> : "Send OTP"}
              </button>

              <p className={styles.tos}>
                By continuing, you agree to our{" "}
                <span className={styles.link}>Terms</span> &amp;{" "}
                <span className={styles.link}>Privacy Policy</span>
              </p>
            </>
          )}

          {/* ── OTP STEP ── */}
          {step === "otp" && (
            <>
              <Logo />
              <h1 className={styles.title}>Verify your number</h1>
              <p className={styles.subtitle}>OTP sent to +91 {phone}</p>

              <div className={styles.otpRow}>
                {otp.map((digit, i) => (
                  <input
                    key={i}
                    ref={(el) => { otpRefs.current[i] = el; }}
                    type="text"
                    inputMode="numeric"
                    maxLength={1}
                    value={digit}
                    className={`${styles.otpBox} ${digit ? styles.otpBoxFilled : ""}`}
                    onChange={(e) => handleOtpChange(i, e.target.value)}
                    onKeyDown={(e) => handleOtpKeyDown(i, e)}
                  />
                ))}
              </div>

              <p className={styles.hint}>
                Hint: mock OTP is{" "}
                <code className={styles.code}>1234</code>
              </p>

              {error && <p className={`${styles.error} ${styles.errorCenter}`}>{error}</p>}

              <button
                className={styles.btn}
                onClick={handleVerifyOTP}
                disabled={loading}
              >
                {loading ? <Spinner /> : "Verify OTP"}
              </button>

              <div className={styles.linkRow}>
                <button
                  className={`${styles.textBtn} ${styles.textBtnMuted}`}
                  onClick={() => {
                    setStep("phone");
                    setOtp(["", "", "", ""]);
                    setError("");
                  }}
                >
                  ← Change number
                </button>
                <span className={styles.sep}>|</span>
                <button
                  className={`${styles.textBtn} ${resendTimer > 0 ? styles.textBtnDisabled : styles.textBtnAccent}`}
                  onClick={handleResend}
                  disabled={resendTimer > 0}
                >
                  {resendTimer > 0 ? `Resend in ${resendTimer}s` : "Resend OTP"}
                </button>
              </div>
            </>
          )}

          {/* ── SUCCESS STEP ── */}
          {step === "success" && (
            <div className={styles.successWrapper}>
              <div className={styles.successIcon}>
                <svg width="28" height="28" viewBox="0 0 24 24" fill="none"
                  stroke="#818cf8" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              </div>
              <h1 className={styles.title}>You're in!</h1>
              <p className={`${styles.subtitle} ${styles.successSub}`}>
                Successfully verified +91 {phone}
              </p>
              <div className={styles.tokenBox}>
                <p className={styles.tokenText}>session_token: mock_jwt_abc123xyz...</p>
              </div>
              <button className={styles.ghostBtn} onClick={handleReset}>
                Sign out &amp; try again
              </button>
            </div>
          )}
        </div>

        <p className={styles.footer}>
          fully frontend · no backend · mock otp
        </p>
      </div>
    </div>
  );
}

